"use strict";

/**
 * Judge only. Do not edit this file.
 *
 * The structure to adopt (spec 3.5). Your agent keeps its own loop and executes the tool itself. Before it
 * does, it calls judge.run with the conversation and the tool call the model made. The skeleton
 * (execution-state-preflight.js) reads the tool's definition, judges, and writes the decision record.
 * Nothing is executed here.
 *
 *   const { createJudge } = require("./judge-only");
 *   const judge = createJudge({ ask, measure, readToolDefinition, measurements, storage, userId });
 *   const r = await judge.run({ unitKey, conversation, toolCall, userChecklist });
 *   // r.key        the record's key: read the record from your storage under it
 *   // r.ask        the gate is waiting on the user
 *   // r.questions  what is still to ask the user about values and conditions
 *   // r.message    the gate's own words, when it could not tell what is wanted: show them as they are
 *   // r.block      the values as code wrote them, and the provider's notices: show them unchanged
 *   // r.notices    the provider's notices on their own, for a round that asks nothing
 *   // r.reason     why, in words
 *   await judge.recordResult(record, { ok, error });   // after YOUR agent executed, or failed to
 *   judge.toolsForModel(tools)   // the skeleton's: the tools as your model is given them, without the labelled lines
 *
 * What run returns carries no arguments for the call and no decision to execute. Both are in the record,
 * and the executing side reads them there (spec 3.5). judge-only-example.js shows the whole of it.
 *
 * This file also holds what the skeleton leaves to the adopting system, none of it specific to a tool:
 *
 *   the model     where the user's words are, what they call the act and when, the comparable form of a
 *                 line or a condition, a value read from the user's words in its declared form (shown
 *                 for the user to approve), and where the user's reply answers a question. It is never
 *                 asked whether a check passed
 *   the engine    every comparison is a JSON Schema, run by a standard validator (Ajv). A schema it
 *                 cannot run leaves the check unverified, never passed
 *
 * gate.js (the demonstration: a whole agent, as a LangGraph flow) judges through this same file.
 */

// The skeleton: one file, copied beside this folder (the repository layout) or into it.
const { createPreflight, labelledLines, toolsForModel, stopFacts, readTranslatedForms, renderValue } = (() => {
  try { return require("./execution-state-preflight"); }
  catch (e) { if (e.code !== "MODULE_NOT_FOUND") throw e; return require("../execution-state-preflight"); }
})();

const Ajv = require("ajv");
const addFormats = require("ajv-formats");

// The validator. strict: a keyword it does not know is an error, not something to skip — a declared
//   check that cannot be run must not read as a check that passed.
const ajv = new Ajv({ strict: true, allErrors: true });
addFormats(ajv);
const compiled = new WeakMap();

// { ok: true|false, errors } when the value was checked; { error } when the schema cannot be compiled.
function checkAgainst(schema, value) {
  if (!schema || typeof schema !== "object") return { error: "no schema" };
  let validate = compiled.get(schema);
  if (!validate) {
    try { validate = ajv.compile(schema); } catch (e) { return { error: e.message }; }
    compiled.set(schema, validate);
  }
  const ok = validate(value);
  return { ok, errors: ok ? null : ajv.errorsText(validate.errors) };
}

const WHEN_CASES = ["immediate", "scheduled", "conditional", "recurring"];

function squash(s) {
  return String(s).toLowerCase().replace(/[.,!?;:'"()]/g, " ").replace(/\s+/g, " ").trim();
}

// Where a quoted value sits in a segment's text: the first exact occurrence, else the first that
//   differs only in case. null when it is not there.
function locateQuote(text, quote) {
  if (typeof text !== "string" || typeof quote !== "string" || quote === "") return null;
  let at = text.indexOf(quote);
  if (at < 0) {
    const lower = text.toLowerCase().indexOf(quote.toLowerCase());
    if (lower >= 0) at = lower;
  }
  return at >= 0 ? [at, at + quote.length] : null;
}

function trustedText(instruction) {
  return (instruction ?? []).filter(s => s?.trust === "user").map(s => s.text).join("\n");
}
const segmentsOf = instruction => (instruction ?? []).map((s, i) => ({ index: i, trust: s?.trust, text: s?.text }));
const fieldsOf = tool => Object.entries(tool?.inputSchema?.properties ?? {}).map(([n, p]) =>
  `  ${n}: ${[p?.type, p?.format && `format ${p.format}`, p?.pattern && `pattern ${p.pattern}`].filter(Boolean).join(", ")}`).join("\n");

// The comparable forms a line can be put into (the skeleton's kinds), told to the model that writes one.
const FORM_KINDS = [
  // A field that is also a measurement: given the list of measurements, a real model put "The location is
  //   the place the seller names" into user_approval in most runs, value_source in some, and once no form,
  //   while the same line for the item, which is not a measurement, was value_source every time.
  '{"kind": "value_source", "slot": "<field>"}  who may give a field\'s value. With [Required]: only the system ' +
    '(a measurement). With [Verify]: only the user; add "measured_within_user_range": true when a measurement may ' +
    'also give it, inside a range the user sets. A line that says who gives a field\'s value is this kind, also ' +
    'for a field that is also a measurement',
  '{"source": "measured_data", "measure": "<measurement>", "schema": <JSON Schema>}  a fact the system measures, ' +
    'and the JSON Schema it must satisfy. Only measurements in the list below can be named',
  '{"kind": "user_approval"}  [Verify] only: the user confirms it each time, for the values of the fields it ' +
    'constrains. Not for a line that only says who gives a value',
  '<a JSON Schema>  a user\'s condition on one field\'s value; set constrains to that field',
];

/**
 * @param ask   The model call: (model, system, user, hook) → parsed JSON. connect.js supplies it.
 * @param model The model's name, recorded on each translation it writes.
 * @param measure, readToolDefinition   connect.js's ports: the gate calls them itself.
 * @param measurements  The names connect.js can measure. A form may name only these.
 * @param unitKey  The conversation's id (the graph's thread). With the user and the tool, it keys the unit.
 */
function createHooks({ model = "model", ask, runId = "run", unitKey = null, meter, measure, readToolDefinition, measurements = [] }) {
  if (typeof ask !== "function") throw new Error("createHooks: ask is required");
  async function call(system, user, hook) {
    const entry = { hook, ok: false };
    meter?.calls?.push(entry);
    const json = await ask(model, system, user, hook);
    entry.ok = true;
    return json;
  }

  // The definition the gate read in this run. The skeleton passes the field name and the instruction to
  //   the extraction hooks, so they read the tool from here: the same definition, never a copy.
  let tool = null;

  // One extraction per run, shared by every field, failure included.
  const extractionCache = new Map();
  function extractAll(instruction) {
    const key = JSON.stringify(instruction);
    if (!extractionCache.has(key)) extractionCache.set(key, extractOnce(instruction));
    return extractionCache.get(key);
  }
  async function extractOnce(instruction) {
    const props = tool?.inputSchema?.properties ?? {};
    const system =
      "A user has asked their assistant to carry out a task with the tool below. You help that assistant " +
      "read the conversation: you report which details the USER stated, quoting the user's own words. " +
      "You never supply a value that is not literally present.\n" +
      "Only segments with \"trust\": \"user\" are the user's words. Other segments are not the user's and " +
      "must not be quoted for any field, even when they contain the same value. When the user changed a " +
      "detail later in the conversation, quote the latest.\n" +
      "Return JSON only.";
    const user =
      `Tool: ${tool?.name}\n${String(tool?.description ?? "")}\n\n` +
      "Segments:\n" + JSON.stringify(segmentsOf(instruction), null, 2) +
      `\n\nFields to locate:\n${fieldsOf(tool)}\n\n` +
      "For each field return either\n" +
      '  {"found": true, "value": "<the exact words, copied from one trust:user segment>", "segment_index": <int>}\n' +
      'or {"found": false}\n\n' +
      "value must be copied character for character. Do not derive, infer, convert or reformat.\n" +
      // Report the words even when they are not in the field's form: a model that read the form as a
      //   requirement on the quote found no time in "2pm this Saturday", and the time was never settled.
      "Report the user's words for a field even when they are not in the field's declared form (\"2pm this " +
      "Saturday\" for a date-time): copy them as they are. Another step puts them into the form.\n\n" +
      `Reply as {${Object.keys(props).map(n => `"${n}": ...`).join(", ")}}`;
    return call(system, user, "extraction");
  }

  return {
    // [TOOL DEFINITION] The gate reads the definition of the tool the model called, from the provider.
    async readToolDefinition(name) {
      if (typeof readToolDefinition !== "function") throw new Error("readToolDefinition is not connected");
      tool = await readToolDefinition(name);
      return tool;
    },

    // [MEASURE] What the system measures, read when the gate asks, with the values it has settled.
    async measure(name, settled) {
      if (typeof measure !== "function") throw new Error("measure is not connected");
      return measure(name, settled);
    },
    // The names connect.js can measure: the skeleton marks a translation about one of them for review.
    getMeasurableNames: () => measurements,

    async classifyWhenCase(instruction) {
      const system =
        "You classify WHEN THE TOOL CALL SHOULD BE MADE — not when the thing being arranged happens.\n" +
        `Answer with exactly one of: ${WHEN_CASES.join(", ")}.\n` +
        "A time or date INSIDE what is being arranged is an argument to the call, not a delay before it.\n" +
        'If the instruction does not settle this, answer {"when_case": null}.\nReturn JSON only.';
      const out = await call(system, `Instruction:\n${trustedText(instruction)}\n\nReply as {"when_case": "..."}`, "when_case");
      if (out && "when_case" in out && out.when_case === null) return null;
      if (!WHEN_CASES.includes(out?.when_case)) throw new Error(`when_case reply unusable: ${JSON.stringify(out).slice(0, 120)}`);
      return out.when_case;
    },

    // A located claim; the gate checks it (spec 4.1).
    async extractUserActionName(instruction) {
      const segments = segmentsOf(instruction).filter(s => s.trust === "user");
      const out = await call(
        "You report what the speaker calls the action they are asking for, quoting their own words exactly. " +
        "Do not paraphrase or use tool names. Return JSON only.",
        "Segments:\n" + JSON.stringify(segments, null, 2) +
        '\n\nReply as {"action_name": "<exact words>", "segment_index": <int>} or {"action_name": null}.', "action_name");
      if (out && "action_name" in out && out.action_name === null) return { none: "absent" };
      const quote = typeof out?.action_name === "string" ? out.action_name.trim() : "";
      if (!quote || quote.length > 60) throw new Error("action name unusable");
      const idx = out?.segment_index;
      const text = Number.isInteger(idx) ? (instruction ?? [])[idx]?.text : undefined;
      return { value: quote, segment_index: idx ?? null, span: locateQuote(text, quote) };
    },

    // Whether the act the user named is what the called tool does. A judgment (spec 8.1: tool selection
    //   is not proven in code); the record says so (matched_by "judgment").
    async confirmToolNameMatchesIntent(userActionName, mcpTool) {
      const out = await call(
        "You check whether the action a user asked for, in their own words, is what a tool does. Answer " +
        "from the words and the tool's description only. Return JSON only.",
        `The user asked: ${JSON.stringify(userActionName)}\n\nTool: ${mcpTool?.name}\n${String(mcpTool?.description ?? "")}\n\n` +
        'Reply as {"approved": true|false, "reason": "<one sentence>"}', "tool_match");
      return { approved: out?.approved === true, reason: typeof out?.reason === "string" ? out.reason : "no reason given" };
    },

    // Returns a location and the words at it, never a value of its own. Words that are not in the
    //   slot's declared form ("2pm this Saturday" for a date-time) fail validateFieldSchema; the model's
    //   reading of them is proposed (proposeValue) and shown for the user to approve.
    async extractFromInstruction(fieldName, instruction) {
      let all;
      try { all = await extractAll(instruction); }
      catch (e) { throw new Error(`extraction failed: ${e.message}`); }
      const hit = all?.[fieldName];
      if (hit?.found === false) return { none: "absent" };
      if (!hit || hit.found !== true) return undefined;
      const { value, segment_index } = hit;
      const seg = (instruction ?? [])[segment_index];
      return { value, segment_index, span: locateQuote(seg?.text, value) };
    },

    // Equality of the words at the span and the value. Words inside a limit the user declared never
    //   reach this hook: the skeleton refuses them first ([LIMIT WORDING]).
    spanSupportsValue(value, textAtSpan) {
      return squash(value) === squash(textAtSpan);
    },

    // The field's own schema, as the provider declared it, checked by the validator. A schema it
    //   cannot compile is a check not made: unverified, which the skeleton sends to definition repair.
    validateFieldSchema(value, schema, ctx, fieldName) {
      if (!schema) return null;
      const out = checkAgainst(schema, value);
      if (out.error) return { unverified: `"${fieldName}" has a schema the validator cannot run: ${out.error}` };
      return out.ok ? null : `"${fieldName}" does not match its declared schema: ${out.errors}; got ${JSON.stringify(value)}`;
    },

    // The whole argument object against the tool's input schema, by the same validator.
    validatePayload(args, inputSchema) {
      if (!inputSchema) return null;
      const out = checkAgainst(inputSchema, args);
      if (out.error) return { unverified: `the input schema cannot be run by the validator: ${out.error}` };
      return out.ok ? null : `the arguments do not match the input schema: ${out.errors}`;
    },

    // The comparable form of one condition, written from its words. For a provider's line the gate keeps
    //   it and compares in it; for a user's condition the user confirms it first. A reply that is not one
    //   of the kinds, or names a measurement this system cannot read, is no form.
    async proposeComparableForm({ declared_by, label, wording, mcpTool }) {
      const props = mcpTool?.inputSchema?.properties ?? {};
      const out = await call(
        "You put one condition, written in words, into a form a program can compare. You do not decide " +
        "whether it holds. Use only the kinds listed. If none fits, answer {\"form\": null}. Return JSON only.",
        // Each field with its declared form: a schema in a form is run on the field's whole value, as the
        //   tool receives it. Given only the names, a real model wrote a time-of-day pattern for "Nothing
        //   after 8pm" that no date-time value could match.
        `Tool: ${mcpTool?.name}\nFields, each with its declared form (a schema in your form is applied to the ` +
        `field's whole value, exactly as the tool receives it):\n${fieldsOf(mcpTool)}\n` +
        `Measurements this system can read: ${measurements.length ? measurements.join(", ") : "(none)"}\n\n` +
        `Declared by: ${declared_by}${label ? `\nLabel: [${label}]` : ""}\nCondition: ${wording}\n\n` +
        `Kinds:\n${FORM_KINDS.map(k => `  ${k}`).join("\n")}\n\n` +
        'Reply as {"form": {"compare": <one of the kinds>, "constrains": ["<field>", ...]}} or {"form": null}',
        "comparable_form");
      const f = out?.form;
      // The model looked and no form fits: said so, not left as no answer.
      if (out && typeof out === "object" && "form" in out && f === null) return null;
      if (!f || typeof f !== "object" || !f.compare || typeof f.compare !== "object") return undefined;
      if (f.compare.source === "measured_data" && !measurements.includes(f.compare.measure)) return undefined;
      const constrains = Array.isArray(f.constrains) ? f.constrains.filter(n => n in props) : [];
      return { compare: f.compare, constrains, by: model };
    },

    // The conditions the user stated (spec 4.4), as quotes the skeleton locates in the user's own words.
    //   Only the user's segments; a limit, a range, a "never" or "only" is a condition, a value is not.
    async extractUserConditions(instruction, mcpTool) {
      const props = mcpTool?.inputSchema?.properties ?? {};
      const out = await call(
        "You find the conditions the USER set on a task: limits, ranges, things they never or only accept. " +
        "A value they gave is not a condition. Quote their own words exactly, from segments with \"trust\": " +
        "\"user\" only. Report every condition the user set, also one they later took back: never leave it " +
        "out. For one taken back, also quote the user's words that take it back, in withdrawn_by. Return JSON only.",
        `Tool: ${mcpTool?.name}\nFields: ${Object.keys(props).join(", ")}\n\nSegments:\n${JSON.stringify(segmentsOf(instruction), null, 2)}\n\n` +
        'Reply as {"conditions": [{"quote": "<exact words>", "segment_index": <int>, "constrains": ["<field>"], ' +
        '"withdrawn_by": {"quote": "<exact words>", "segment_index": <int>} (only when taken back)}]}, ' +
        'or {"conditions": []} when the user set none.',
        "user_conditions");
      if (!Array.isArray(out?.conditions)) throw new Error("user conditions reply unusable");
      if (out.conditions.length === 0) return { none: "absent" };
      return out.conditions.map(c => {
        const seg = (instruction ?? [])[c?.segment_index];
        const w = c?.withdrawn_by && typeof c.withdrawn_by === "object" ? c.withdrawn_by : null;
        const wseg = w ? (instruction ?? [])[w.segment_index] : null;
        return { quote: c?.quote, segment_index: c?.segment_index ?? null, span: locateQuote(seg?.text, c?.quote),
                 constrains: Array.isArray(c?.constrains) ? c.constrains : [],
                 ...(w ? { withdrawn_by: { quote: w.quote, segment_index: w.segment_index ?? null, span: locateQuote(wseg?.text, w.quote) } } : {}) };
      });
    },

    // A value for one blank, read from the user's words and written in the field's declared form. Shown
    //   to the user with the question; it settles nothing until the user approves it.
    async proposeValue(fieldName, instruction, schema) {
      const p = schema ?? {};
      const out = await call(
        // The value is the user's; what the form needs beyond it may come from what the system gave. With
        //   the user's words alone, a model that kept to them wrote no date-time: the year and the time zone
        //   were only in the account context. The user approves what is shown either way (spec 5.2).
        "You read what the user said and write the value of one field in the field's declared form. The value " +
        "itself, which moment or which thing, comes only from the user's words (segments with \"trust\": \"user\"). " +
        "What the form needs beyond it, such as the year, or the time zone the tool's description points to, may " +
        "be taken from the other segments. If the user's words do not give one value, answer {\"value\": null}. " +
        "The user will be shown your value to approve. Return JSON only.",
        `Tool: ${tool?.name}\n${String(tool?.description ?? "")}\n\nSegments:\n${JSON.stringify(segmentsOf(instruction), null, 2)}\n\n` +
        `Field: ${fieldName}: ${[p.type, p.format && `format ${p.format}`, p.pattern && `pattern ${p.pattern}`].filter(Boolean).join(", ")}\n\n` +
        'Reply as {"value": "<value>"} or {"value": null}',
        "propose_value");
      return out && "value" in out && out.value !== null && out.value !== undefined ? { value: out.value } : undefined;
    },

    // Where the user's reply answers each question the gate asked. Quotes, located here; the skeleton
    //   keeps a claim only for a question it asked, in the user's words after it ([REPLIES]).
    async readReplies(instruction, questions) {
      const shown = questions.map(q => ({ target: q.target, asked_after_segment: q.asked_through - 1, ...aboutQuestion(q) }));
      const out = await call(
        "The assistant asked the user the questions below. Report where the user's words answer each one. " +
        "Quote the user's own words exactly, from segments with \"trust\": \"user\" that come after the " +
        "question was asked. A yes or no is an answer. One yes or no after several questions answers each " +
        "of them, unless the user says which one they mean. Leave a question out only when, after it was " +
        "asked, the user typed a value or a change instead of a yes or no for it: what they typed before " +
        "the question does not count either way. Return JSON only.",
        `Questions:\n${JSON.stringify(shown, null, 2)}\n\nSegments:\n${JSON.stringify(segmentsOf(instruction), null, 2)}\n\n` +
        'For each question answered, one of\n' +
        '  {"target": "<target>", "answer": true|false, "quote": "<exact words>", "segment_index": <int>}\n' +
        '  {"target": "<target>", "none": "absent", "quote": "<exact words>", "segment_index": <int>}  (a value question the user says has no value)\n\n' +
        'Reply as {"replies": [...]}',
        "replies");
      if (!Array.isArray(out?.replies)) throw new Error("replies reply unusable");
      if (out.replies.length === 0) return { none: "absent" };
      return out.replies.map(r => {
        const seg = (instruction ?? [])[r?.segment_index];
        return { ...r, span: locateQuote(seg?.text, r?.quote) };
      });
    },

    // A measured fact against the form's schema. The skeleton measures what the form names and hands the
    //   result here (ctx.measurements); value_source and user_approval forms it decides itself.
    verifyProviderCondition(cond, ctx) {
      const c = cond.compare;
      if (c?.source !== "measured_data" || typeof c.measure !== "string") {
        return { status: "unverified", source: null, note: "the form names no measurement to check" };
      }
      const m = ctx?.measurements?.[c.measure];
      if (m?.valid !== true) return { status: "unverified", source: null, note: `no measurement of ${c.measure}` };
      const out = checkAgainst(c.schema, m.value);
      if (out.error) return { status: "unverified", source: null, note: `the form's schema cannot be run: ${out.error}` };
      return out.ok
        ? { status: "checked", source: "measured_data", note: `${c.measure} = ${JSON.stringify(m.value)}` }
        : { status: "unmet", source: "measured_data", note: `${c.measure} = ${JSON.stringify(m.value)}: ${out.errors}` };
    },

    // A user's condition with a JSON Schema form, against the value the slot settled on. One with no
    //   form, or of kind user_approval, is the user's to approve, and the skeleton decides it from the
    //   user's bound answer; it reaches this hook only while no answer holds.
    verifyUserChecklistItem(item, ctx) {
      const slot = Array.isArray(item?.constrains) ? item.constrains[0] : undefined;
      if (!item?.compare || !slot) {
        return { ...item, status: "unverified", source: null, note: "no confirmed comparison form" };
      }
      const field = (ctx?.fields ?? []).find(f => f.name === slot);
      const out = checkAgainst(item.compare, field?.value);
      if (out.error) {
        return { ...item, status: "unverified", source: null, note: `the confirmed schema cannot be run: ${out.error}` };
      }
      return out.ok
        ? { ...item, status: "verified", source: field?.source ?? null, note: `${slot}=${JSON.stringify(field.value)} satisfies the confirmed schema` }
        : { ...item, status: "unmet", source: field?.source ?? null, note: `${slot}=${JSON.stringify(field?.value)}: ${out.errors}` };
    },

    // The unit: this user, this tool, this conversation. The skeleton reads the unit's records under it:
    //   what was asked, and how often (spec 4.5, 4.6). Another tool in the same conversation is another unit.
    buildActionKey(userId, fixed) {
      return `${userId}:${fixed?.c3_provider_action_name ?? "unknown"}:${unitKey ?? runId}`;
    },
  };
}

// Append-only, and load returns only the most recent executed record (spec 5.2).
function createStorage() {
  const m = new Map();
  return {
    async persist(key, record) {
      const k = key ?? "UNKEYED";
      m.set(k, [...(m.get(k) ?? []), record]);
      return record;
    },
    async load(key) {
      const arr = m.get(key) ?? [];
      for (let i = arr.length - 1; i >= 0; i--) if (arr[i]?.execution_decision === "executed") return arr[i];
      return null;
    },
    // Every record under the key, oldest first: what a unit was asked, and the kept translations.
    async list(key) {
      return [...(m.get(key) ?? [])];
    },
  };
}

// [QUESTION] The words of a question, written by the model from what the gate listed and the provider's
//   lines on each value. The values are not the model's: code appends them under these words, as they
//   will be used, and a yes approves exactly those. Both flows ask through this one function.
//   say(model, system, user, hook) → the model's plain text, when connected: a question is words, and a
//   real model asked for JSON here answered in plain words whenever its own earlier turn was in the
//   conversation. Without say, ask() is used with a JSON reply. null when no words came back: the caller
//   asks with the list alone.
const QUESTION_SYSTEM =
  "You ask the user, in conversation, for what is still missing before a tool can run. Write one short " +
  "message, in the language the user writes in. Ask about every item below, and follow the tool's lines " +
  "on how to ask. Do not write any value yourself: the values to approve are shown under your message, " +
  "exactly as they will be used.";
// What a question is about, as the model writing it and the model reading the reply are told: the same
//   words for both. A model told only a question's kind guessed: "withdraw" became "Cancel the pickup".
function aboutQuestion(q) {
  return {
    kind: q.kind,
    ...(q.kind === "value" ? { field: q.slot, shown: q.candidate?.shown_text ?? null } : {}),
    ...(q.kind === "approve" ? { item: q.description, for: q.shown_text } : {}),
    ...(q.kind === "confirm_form" ? { said: q.wording, checked_like_this: q.text } : {}),
    ...(q.kind === "withdraw" ? { remove_condition: q.stated_as, because_you_said: q.withdrawn_by } : {}),
  };
}
async function writeQuestion({ ask, say, model = "model" }, { questions, conversation }) {
  const user =
    `Items:\n${JSON.stringify((questions ?? []).map(q => ({ ...aboutQuestion(q),
      lines: (q.lines ?? []).map(l => `[${l.label}] ${l.text}`) })), null, 2)}\n\n` +
    `Conversation:\n${JSON.stringify(segmentsOf(conversation), null, 2)}`;
  const words = t => (typeof t === "string" && t.trim() ? t.trim() : null);
  try {
    if (typeof say === "function") {
      const t = words(await say(model, `${QUESTION_SYSTEM} Write only the message itself.`, user, "question"));
      // A model that answers in JSON anyway: its message is the words.
      if (t && t.startsWith("{")) { try { const o = JSON.parse(t); if (words(o?.message)) return words(o.message); } catch {} }
      return t;
    }
    const out = await ask(model, `${QUESTION_SYSTEM} Return JSON only.`, `${user}\n\nReply as {"message": "..."}`, "question");
    return words(out?.message);
  } catch { return null; }
}

// How a conversation is shown to the agent's model: the user's words as the user's, anything else that
//   arrived as context, marked as not the user's, and what the assistant said as the assistant's.
//   What the gate said after a call goes back as that call's result, not as the model's own words: a
//   real model, shown the gate's reason as something it had said itself, took it back on the next turn
//   as made up ("I never called the scheduling tool"). A segment from afterCall carries the call.
const CALL_RESULT = {
  waiting: "Not run yet. The system is asking the user first. The user was shown:",
  not_executed: "Not run. The user was told:",
  executed: "Run.",
  failed: "The call failed:",
};
function messagesFor(conversation) {
  return (conversation ?? []).flatMap(s => {
    const c = s.after_call;
    if (c) {
      const result = [CALL_RESULT[c.status] ?? c.status, s.text].filter(Boolean).join("\n");
      return [{ role: "assistant", content: "", tool_calls: [{ id: c.id, name: c.name, args: c.arguments ?? {} }] },
              { role: "tool", tool_call_id: c.id, name: c.name, content: result }];
    }
    return [s.trust === "assistant"
      ? { role: "assistant", content: s.text }
      : { role: "user", content: s.trust === "user" ? s.text : `[context, not the user's words] ${s.text}` }];
  });
}
// The segment that ends a call's turn: the gate reads it as the assistant's words (text), the model as
//   its call and the call's result (messagesFor). status: waiting, not_executed, executed, failed.
let callSeq = 0;
function afterCall(toolCall, status, text = "") {
  return { trust: "assistant", text,
           after_call: { id: toolCall?.id ?? `call_${++callSeq}`, name: toolCall?.name ?? null, arguments: toolCall?.arguments ?? null, status } };
}

// Why it did not run, told to the user. The facts are the skeleton's (stopFacts), read from the record
//   the executing side decided from; the model only puts them into words. Without its words, a plain
//   sentence: the user is told either way. A real run held on a [Required] line ended with nothing said.
const STOP_SYSTEM =
  "You tell the user, in conversation, that what they asked for was not carried out, and why. Write one " +
  "short message, in the language the user writes in. Say only what the items say: do not add a reason, " +
  "do not say it will run later unless an item says so, and do not suggest a way around a condition. " +
  "set_by tells whose condition it is: the tool's provider, or the user's own. found is what was found.";
const STOP_FALLBACK = "This was not carried out.";
async function writeStop({ ask, say, model = "model" }, { record, conversation }) {
  const facts = stopFacts(record);
  const user =
    `Not carried out (${facts.decision ?? "no decision"}). Items:\n${JSON.stringify(facts.items, null, 2)}\n\n` +
    `Conversation:\n${JSON.stringify(segmentsOf(conversation), null, 2)}`;
  const words = t => (typeof t === "string" && t.trim() ? t.trim() : null);
  let text = null;
  try {
    if (typeof say === "function") {
      text = words(await say(model, `${STOP_SYSTEM} Write only the message itself.`, user, "stop"));
      if (text && text.startsWith("{")) { try { const o = JSON.parse(text); if (words(o?.message)) text = words(o.message); } catch {} }
    } else {
      text = words((await ask(model, `${STOP_SYSTEM} Return JSON only.`, `${user}\n\nReply as {"message": "..."}`, "stop"))?.message);
    }
  } catch { text = null; }
  return { message: text ?? STOP_FALLBACK, facts };
}

// One round: judge the tool call against the conversation so far, and write the record. Returns the
//   skeleton's state. gate.js reads it; createJudge hands on only what there is to ask.
//   intentAttempt: how many times this conversation was already asked to restate what it wants done.
//   The caller carries it (the skeleton's contract): those records have no key to count them under.
//   How often the tool was asked about, the skeleton counts itself, from the unit's records.
async function judgeRound({ ask, model = "model", runId = "run", unitKey = null, measure, readToolDefinition, measurements = [],
                            storage, userId = "user", conversation, toolCall, userChecklist, intentAttempt = 0 }) {
  const hooks = createHooks({ ask, model, runId, unitKey, measure, readToolDefinition, measurements });
  const preflight = createPreflight({ hooks, storage });
  const st = await preflight.runPreflight({
    userId, instruction: conversation, toolCall, preSetData: {},
    userChecklist, intent_attempt: intentAttempt, tool_attempt: 0,
  });
  await preflight.recordExecutionState(st);
  return st;
}

// The executing side reports what happened, onto the record it executed from. Only an executed record
//   is what a later run may carry values over from (spec 5.2, prior_state).
async function writeResult({ ask, model = "model", runId = "result", measure, readToolDefinition, measurements = [], storage }, record, { ok, error } = {}) {
  if (!record || typeof record !== "object" || !record.action_key) throw new Error("recordResult: a decision record read from storage is required");
  const hooks = createHooks({ ask, model, runId, measure, readToolDefinition, measurements });
  const preflight = createPreflight({ hooks, storage });
  return preflight.recordExecutionState({
    ...record,
    execution_decision: ok ? "executed" : "failed",
    reason: `${record.reason} / ${ok ? "call succeeded" : `call failed: ${error ?? "unknown"}`}`,
    timestamp: new Date().toISOString(),
  });
}

/**
 * @param ask, measure, readToolDefinition, storage   your connections (connect.js)
 * @param measurements   the names your system can measure (for comparable forms)
 * storage needs persist, load and list. Keep it append-only, where the agent cannot rewrite it (spec 8.2).
 */
function createJudge({ ask, measure, readToolDefinition, measurements = [], storage, userId = "user", model = "model", runId = "judge" }) {
  for (const [n, f] of Object.entries({ ask, readToolDefinition })) {
    if (typeof f !== "function") throw new Error(`createJudge: ${n} is required`);
  }
  if (typeof storage?.persist !== "function" || typeof storage?.load !== "function" || typeof storage?.list !== "function") {
    throw new Error("createJudge: storage with persist, load and list is required");
  }
  let round = 0;
  // How often each conversation was asked to restate what it wants done (see judgeRound).
  const intentAttempts = new Map();

  // unitKey: the same for every turn of one conversation. A reply counts only for a question asked in it.
  // conversation: every segment so far, each with who wrote it ("user" only for what the user typed).
  async function run({ unitKey, conversation, toolCall, userChecklist = [] }) {
    round += 1;
    const st = await judgeRound({ ask, model, runId: `${runId}-${round}`, unitKey, measure, readToolDefinition, measurements,
                                  storage, userId, conversation, toolCall, userChecklist,
                                  intentAttempt: intentAttempts.get(unitKey) ?? 0 });
    // Raised only while the gate keeps asking for a restatement; anything else starts the count again.
    const next = st.gate?.next_intent_attempt;
    if (Number.isInteger(next)) intentAttempts.set(unitKey, next); else intentAttempts.delete(unitKey);
    const asking = st.execution_decision === "ask_user";
    return {
      key: st.action_key ?? null,
      // The gate is waiting on the user: show the question, add the reply, run again.
      ask: asking,
      questions: asking ? (st.gate?.questions ?? []) : [],
      block: asking ? [...(st.gate?.question_block ?? []), ...(st.gate?.disclosures ?? []).map(d => `Note: ${d.description}`)] : [],
      // The gate's own words, when it could not tell what is wanted, or which tool it maps to. Shown as
      //   they are: there is nothing yet for a model to ask about. options: what to choose between, if any.
      message: typeof st.gate?.user_message === "string" ? st.gate.user_message : null,
      options: st.gate?.branch_options ?? null,
      notices: (st.gate?.disclosures ?? []).map(d => d.description),
      reason: st.reason,
    };
  }

  const recordResult = (record, outcome) =>
    writeResult({ ask, model, runId: `${runId}-result`, measure, readToolDefinition, measurements, storage }, record, outcome);

  return { run, recordResult, toolsForModel };
}

module.exports = {
  createJudge, judgeRound, writeResult, writeQuestion, writeStop, stopFacts, toolsForModel, messagesFor, afterCall, createHooks, createStorage, checkAgainst, segmentsOf, FORM_KINDS, WHEN_CASES,
  createPreflight, labelledLines, readTranslatedForms, renderValue,
};
